rule CobaltStrike_Beacon_Generic {
    meta:
        description = "Detect generic Cobalt Strike Beacon"
        author = "SOC"
        false_positive = true
    strings:
        $pe = { 4D 5A ?? ?? ?? 00 00 00 00 00 00 00 00 00 00 00 }
    condition:
        // original detection condition (simplified)
        $pe and filesize < 5MB
        // whitelist known good hash to suppress false positives
        not (hash.sha256(0) == "a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2e3f4a5b6c7d8e9f0a1b2")
}

